//! The Agent's config file, in the Agent's own terms. Field names and order are
//! what `minicore-agent --config` reads.

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde::{Deserialize, Serialize};

use super::settings::Compaction;
use crate::protocol::Reasoning;

const HEADER: &str = "\
# Generated by minicore-tui on every start; edits here are lost.
# Edit config.toml and models.toml in the TUI directory instead.

";

#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Approval {
    Auto,
    #[default]
    Ask,
    ReadOnly,
}

#[derive(Serialize)]
pub struct AgentFile {
    pub data_dir: PathBuf,
    pub default_profile: String,
    #[serde(rename = "loop", skip_serializing_if = "Option::is_none")]
    pub loop_options: Option<BTreeMap<String, u64>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub compaction: Option<Compaction>,
    pub profiles: BTreeMap<String, AgentProfile>,
    pub models: BTreeMap<String, AgentModel>,
}

#[derive(Serialize)]
pub struct AgentProfile {
    pub model: String,
    pub reasoning: Reasoning,
    pub tools: Vec<String>,
    pub approval: Approval,
    pub system_prompt: PromptFile,
}

/// The Agent reads the file itself, so the TUI never holds the prompt text.
#[derive(Serialize)]
pub struct PromptFile {
    pub file: PathBuf,
}

#[derive(Serialize)]
pub struct AgentModel {
    pub provider: String,
    pub model: String,
    pub base_url: String,
    pub api_key_env: String,
    pub physical_context_window: u32,
    pub output_budget_tokens: u32,
    pub safety_margin_tokens: u32,
    pub supported_reasoning: Vec<Reasoning>,
    pub supports_tools: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_timeout_seconds: Option<u64>,
}

impl AgentFile {
    pub fn render(&self) -> Result<String, String> {
        let body = toml::to_string(self).map_err(|error| error.to_string())?;
        Ok(format!("{HEADER}{body}"))
    }
}
